export async function manuallyFailReviewRun(
  env: Env,
  reviewId: string
): Promise<{ action: 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
  const review = await getReviewRun(env.DB, reviewId);
  if (!review) {
    return { action: 'failed', review: null };
